## JavaScript

```javascript
class Accordion {
  constructor(container) {
    this.container = container;
    this.buttons = [...container.querySelectorAll('.accordion__trigger')];
    this.panels = [...container.querySelectorAll('.accordion__panel')];
    this.allowMultiple = container.hasAttribute('data-allow-multiple');

    this.buttons.forEach(btn => {
      btn.addEventListener('click', this.handleClick.bind(this));
    });

    // Optional: arrow key navigation
    this.container.addEventListener('keydown', this.handleKeydown.bind(this));
  }

  handleClick(e) {
    const btn = e.currentTarget;
    const isExpanded = btn.getAttribute('aria-expanded') === 'true';

    if (!this.allowMultiple) {
      // Close all others
      this.buttons.forEach(b => {
        b.setAttribute('aria-expanded', 'false');
      });
      this.panels.forEach(p => {
        p.hidden = true;
      });
    }

    // Toggle clicked
    btn.setAttribute('aria-expanded', isExpanded ? 'false' : 'true');
    const panel = document.getElementById(btn.getAttribute('aria-controls'));
    panel.hidden = isExpanded;
  }

  handleKeydown(e) {
    const index = this.buttons.indexOf(document.activeElement);
    if (index === -1) return;

    let newIndex;
    if (e.key === 'ArrowDown') {
      newIndex = index === this.buttons.length - 1 ? 0 : index + 1;
    } else if (e.key === 'ArrowUp') {
      newIndex = index === 0 ? this.buttons.length - 1 : index - 1;
    } else if (e.key === 'Home') {
      newIndex = 0;
    } else if (e.key === 'End') {
      newIndex = this.buttons.length - 1;
    } else {
      return;
    }

    e.preventDefault();
    this.buttons[newIndex].focus();
  }
}

document.querySelectorAll('.accordion').forEach(el => new Accordion(el));
```

---

## CSS

```css
.accordion {
  border: 1px solid #ccc;
  border-radius: 4px;
  overflow: hidden;
}

.accordion__heading {
  margin: 0;
}

.accordion__trigger {
  width: 100%;
  text-align: left;
  padding: 16px;
  background: #f9f9f9;
  border: none;
  border-bottom: 1px solid #ccc;
  font-size: 1rem;
  font-weight: 600;
  cursor: pointer;
  display: flex;
  justify-content: space-between;
  align-items: center;
}

/* Arrow icon using CSS — toggles on expanded state */
.accordion__trigger::after {
  content: '▼';
  font-size: 0.75em;
  transition: transform 0.2s ease;
}

.accordion__trigger[aria-expanded="true"]::after {
  transform: rotate(-180deg);
}

.accordion__trigger:hover {
  background: #eef2ff;
}

.accordion__trigger:focus-visible {
  outline: 3px solid #0066cc;
  outline-offset: -3px;
}

.accordion__panel {
  padding: 16px;
}

.accordion__panel[hidden] {
  display: none;
}

/* Animate open/close (respects reduced motion) */
@media (prefers-reduced-motion: no-preference) {
  .accordion__panel {
    animation: slideDown 0.2s ease;
  }
  @keyframes slideDown {
    from { opacity: 0; transform: translateY(-4px); }
    to { opacity: 1; transform: translateY(0); }
  }
}
```

